import { defineQuery } from "next-sanity";

// All GROQ queries for the public website. Only published content is returned (the
// client uses the "published" perspective) and anything with "Show on website"
// turned off is filtered out here. Result types are generated by `yarn typegen`.

/** Shared by every page: header, footer, social links, CV and SEO defaults. */
export const SITE_QUERY = defineQuery(`{
  "settings": *[_id == "siteSettings"][0]{
    siteTitle,
    seoDescription,
    contactEmail,
    footerText,
    announcement,
    pageSeo,
    shareImage{ alt, asset->{ url, metadata{ dimensions{ width, height } } } }
  },
  "profile": *[_id == "profile"][0]{
    name,
    title,
    focusDescriptor,
    monogram,
    statement,
    availability
  },
  "socialLinks": *[_type == "socialLink" && isVisible != false] | order(orderRank){
    _id,
    platform,
    label,
    url
  },
  "cv": *[_id == "cv" && isVisible == true && defined(file.asset)][0]{
    buttonLabel,
    "url": file.asset->url
  }
}`);

/** Full profile for the homepage and About page. */
export const PROFILE_QUERY = defineQuery(`*[_id == "profile"][0]{
  name,
  title,
  focusDescriptor,
  greeting,
  headline,
  headlineHighlight,
  heroIntro,
  rightNow[]{ _key, label, value },
  introHeading,
  introParagraphs,
  aboutHeading,
  biography,
  focusAreas[]{ _key, title, description },
  quickFacts[]{ _key, label, value },
  interests,
  availability,
  location,
  showPhoto,
  photo{ alt, crop, hotspot, asset->{ _id, url, metadata{ dimensions{ width, height }, lqip } } },
  "currentRole": currentRole->{
    _id,
    organisation,
    title,
    employmentType,
    location,
    startDate,
    endDate,
    isCurrent,
    datePrecision,
    summary,
    contributions,
    technologies
  }
}`);

/** Every visible project, in Studio order. Cards for the homepage and Projects page. */
export const PROJECTS_QUERY = defineQuery(`*[_type == "project" && isVisible != false && defined(slug.current)] | order(orderRank){
  _id,
  name,
  "slug": slug.current,
  category,
  summary,
  projectsPageSummary,
  status,
  statusLabel,
  features,
  technologies,
  stackIsPlanned,
  panelInitials,
  thumbnail{ alt, crop, hotspot, asset->{ _id, url, metadata{ dimensions{ width, height }, lqip } } },
  isRepoPrivate,
  repoUrl,
  liveUrl,
  extraLinks[]{ _key, label, url },
  featured,
  listing
}`);

/** One case study. Only visible projects in the main section have a page. */
export const PROJECT_QUERY = defineQuery(`*[_type == "project" && slug.current == $slug && isVisible != false && listing == "main"][0]{
  _id,
  name,
  "slug": slug.current,
  category,
  summary,
  status,
  statusLabel,
  overview,
  purpose,
  role,
  features,
  technologies,
  stackIsPlanned,
  panelInitials,
  thumbnail{ alt, crop, hotspot, asset->{ _id, url, metadata{ dimensions{ width, height }, lqip } } },
  gallery[]{ _key, alt, caption, crop, hotspot, asset->{ _id, url, metadata{ dimensions{ width, height }, lqip } } },
  isRepoPrivate,
  repoUrl,
  liveUrl,
  extraLinks[]{ _key, label, url },
  "index": count(*[_type == "project" && isVisible != false && defined(slug.current) && orderRank < ^.orderRank])
}`);

/** Slugs of all case-study pages, for static generation and the sitemap. */
export const PROJECT_SLUGS_QUERY = defineQuery(`*[_type == "project" && isVisible != false && listing == "main" && defined(slug.current)] | order(orderRank).slug.current`);

/** Technical focus categories, in Studio order. */
export const SKILLS_QUERY = defineQuery(`*[_type == "skillCategory" && isVisible != false] | order(orderRank){
  _id,
  title,
  summary,
  core,
  familiar
}`);

/** Visible experience entries, in Studio order. */
export const EXPERIENCE_QUERY = defineQuery(`*[_type == "experience" && isVisible != false] | order(orderRank){
  _id,
  organisation,
  title,
  employmentType,
  location,
  startDate,
  endDate,
  isCurrent,
  datePrecision,
  summary,
  contributions,
  technologies
}`);
